#include <getopt.h>
#include <stdio.h>
#include <stdlib.h>

int run(const char *output, int verbose);

static const struct option long_options[] = {
  { "verbose", no_argument, NULL, 'v' },
  { "output", required_argument, NULL, 'o' },
  { NULL, 0, NULL, 0 },
};

int main(int argc, char **argv) {
  int verbose = 0;
  const char *output = "out.txt";
  int c;
  while ((c = getopt_long(argc, argv, "vo:", long_options, NULL)) != -1) {
    switch (c) {
    case 'v':
      verbose = 1;
      break;
    case 'o':
      output = optarg;
      break;
    default:
      fprintf(stderr, "usage: %s [-v] [-o file]\n", argv[0]);
      return EXIT_FAILURE;
    }
  }
  return run(output, verbose);
}
